import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const textOf = (node) =>
  node && node.type === "TEXT" ? node.textContent : undefined;

const name = instance.getString("Name");
const copyright = instance.getString("Copyright");
const privacy = textOf(instance.findText("Privacy"));
const terms = textOf(instance.findText("Terms"));
const help = textOf(instance.findText("Help"));
const links = instance.getBoolean("Show links")
  ? figma.code`<>
  <HvTypography link component="a" href="#">${privacy ?? ""}</HvTypography>
  <HvTypography link component="a" href="#">${terms ?? ""}</HvTypography>
  <HvTypography link component="a" href="#">${help ?? ""}</HvTypography>
</>`
  : undefined;

export default {
  id: "Footer",
  example: figma.code`<HvFooter${attr("name", name)}${attr("copyright", copyright)}${links ? figma.code` links={${links}}` : ""} />`,
  imports: [
    'import { HvFooter, HvTypography } from "@pentaho/uikit-react-core";',
  ],
  metadata: { nestable: true },
};
